'use strict';

angular.module('insight.messages').controller('VerifyMessageController',
  function($scope, $http) {
  $scope.message = {
    address: '',
    signature: '',
    message: ''
  };
  $scope.verification = {
    status: 'unverified',  // ready|loading|verified|error
    result: null,
    error: null,
    address: ''
  };

  $scope.verifiable = function() {
    return ($scope.message.address
            && $scope.message.signature
            && $scope.message.message);
  };
  $scope.verify = function() {
    $scope.verification.status = 'loading';
    $scope.verification.address = $scope.message.address;
    $http.post(window.apiPrefix + '/messages/verify', $scope.message)
      .success(function(data, status, headers, config) {
        if(typeof(data.result) != 'boolean') {
          // API returned 200 but result was not true or false
          $scope.verification.status = 'error';
          $scope.verification.error = null;
          return;
        }

        $scope.verification.status = 'verified';
        $scope.verification.result = data.result;
      })
      .error(function(data, status, headers, config) {
        $scope.verification.status = 'error';
        $scope.verification.error = data;
      });
  };

  // Hide the verify status message on form change
  var unverify = function() {
    $scope.verification.status = 'unverified';
  };
  $scope.$watch('message.address', unverify);
  $scope.$watch('message.signature', unverify);
  $scope.$watch('message.message', unverify);
});


// Source: /root/explorer/sumcoin-explorer/node_modules/insight-sum-ui/public/src/js/controllers/scanner.js
'use strict';

angular.module('insight.system').controller('ScannerController',
  function($scope, $rootScope, $modalInstance, Global, $timeout) {

    $scope.global = Global;
    $scope.scannerLoading = false;
    $scope.scannerError = '';

    $scope.cameraAvailable = !!(
      window.isSecureContext &&
      navigator.mediaDevices &&
      navigator.mediaDevices.getUserMedia
    );

    var video;
    var canvas;
    var context;
    var fileInput;
    var stream = null;
    var scanTimer = null;
    var stopped = false;

    function visibleSearchInput() {
      var inputs = document.querySelectorAll('#search');

      for (var i = 0; i < inputs.length; i++) {
        if (inputs[i].offsetParent !== null) return inputs[i];
      }

      return inputs.length ? inputs[0] : null;
    }

    function submitResult(data) {
      if (!data) return;

      var value = String(data).trim()
        .replace(/^sumcoin:/i, '')
        .split('?')[0];

      stopScanner();

      var input = visibleSearchInput();

      if (!input) {
        window.location.href =
          /^\/es(?:\/|$)/.test(window.location.pathname) ?
            '/es/' :
            '/';
        return;
      }

      var form = input.form;

      angular.element(input)
        .val(value)
        .triggerHandler('input')
        .triggerHandler('change');

      if (form) {
        angular.element(form).triggerHandler('submit');
      }
    }

    function decodeCanvas() {
      try {
        qrcode.width = canvas.width;
        qrcode.height = canvas.height;
        qrcode.imagedata = context.getImageData(
          0, 0, canvas.width, canvas.height
        );
        qrcode.decode();
      } catch (e) {
        return false;
      }

      return true;
    }

    function scanVideo() {
      if (stopped || !stream || !video) return;

      if (video.readyState >= 2) {
        canvas.width = 640;
        canvas.height = 480;
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        decodeCanvas();
      }

      scanTimer = $timeout(scanVideo, 500);
    }

    function scanFile(evt) {
      var files = evt.target.files;
      if (!files || !files.length) return;

      var file = files[0];

      if (file.type.indexOf('image/') !== 0) {
        $scope.$applyAsync(function() {
          $scope.scannerError = 'Please choose an image containing a QR code.';
        });
        return;
      }

      $scope.$applyAsync(function() {
        $scope.scannerLoading = true;
        $scope.scannerError = '';
      });

      var reader = new FileReader();

      reader.onload = function(e) {
        var image = new Image();

        image.onload = function() {
          var max = 900;
          var scale = Math.min(
            max / image.width,
            max / image.height,
            1
          );

          canvas.width = Math.max(1, Math.round(image.width * scale));
          canvas.height = Math.max(1, Math.round(image.height * scale));

          context.drawImage(
            image, 0, 0,
            canvas.width, canvas.height
          );

          try {
            if (!decodeCanvas()) throw new Error('decode failed');
          } catch (err) {
            $scope.$applyAsync(function() {
              $scope.scannerLoading = false;
              $scope.scannerError =
                'No QR code could be read from that image.';
            });
          }
        };

        image.src = e.target.result;
      };

      reader.readAsDataURL(file);
    }

    function startCamera() {
      if (!$scope.cameraAvailable) return;

      navigator.mediaDevices.getUserMedia({
        video: {facingMode: {ideal: 'environment'}},
        audio: false
      }).then(function(s) {
        stream = s;
        video.srcObject = stream;
        return video.play();
      }).then(function() {
        scanVideo();
      }).catch(function(err) {
        $scope.$applyAsync(function() {
          $scope.cameraAvailable = false;
          $scope.scannerError =
            'Camera access was unavailable. You can still choose a QR image below.';
        });
      });
    }

    function stopScanner() {
      if (stopped) return;
      stopped = true;

      if (scanTimer) {
        $timeout.cancel(scanTimer);
        scanTimer = null;
      }

      if (stream) {
        stream.getTracks().forEach(function(track) {
          track.stop();
        });
        stream = null;
      }

      if (fileInput) {
        fileInput.removeEventListener('change', scanFile, false);
      }

      $scope.scannerLoading = false;
      $modalInstance.close();
    }

    qrcode.callback = function(data) {
      $scope.$applyAsync(function() {
        submitResult(data);
      });
    };

    $scope.cancel = stopScanner;

    $modalInstance.opened.then(function() {
      $rootScope.isCollapsed = true;

      $timeout(function() {
        canvas = document.getElementById('qr-canvas');
        video = document.getElementById('qrcode-scanner-video');
        fileInput = document.getElementById('qrcode-camera');

        if (!canvas) return;

        context = canvas.getContext('2d');

        if (fileInput) {
          fileInput.addEventListener('change', scanFile, false);
        }

        startCamera();
      }, 250);
    });

    $scope.$on('$destroy', function() {
      if (!stopped) {
        if (scanTimer) $timeout.cancel(scanTimer);

        if (stream) {
          stream.getTracks().forEach(function(track) {
            track.stop();
          });
        }
      }
    });
  });


// Source: /root/explorer/sumcoin-explorer/node_modules/insight-sum-ui/public/src/js/controllers/search.js
'use strict';

angular.module('insight.search').controller('SearchController',
  function($scope, $routeParams, $location, $timeout, Global, Block, Transaction, Address, BlockByHeight) {
  $scope.global = Global;
  $scope.loading = false;

  var _languagePrefix = function() {
    return /^\/es(?:\/|$)/.test($location.path()) ?
      '/es' :
      '';
  };


  var _badQuery = function() {
    $scope.badQuery = true;

    $timeout(function() {
      $scope.badQuery = false;
    }, 2000);
  };

  var _resetSearch = function() {
    $scope.q = '';
    $scope.loading = false;
  };

  $scope.search = function() {
    var q = $scope.q;
    $scope.badQuery = false;
    $scope.loading = true;

    Block.get({
      blockHash: q
    }, function() {
      _resetSearch();
      $location.path(_languagePrefix() + '/block/' + q);
    }, function() { //block not found, search on TX
      Transaction.get({
        txId: q
      }, function() {
        _resetSearch();
        $location.path(_languagePrefix() + '/tx/' + q);
      }, function() { //tx not found, search on Address
        Address.get({
          addrStr: q
        }, function() {
          _resetSearch();
          $location.path(_languagePrefix() + '/address/' + q);
        }, function() { // block by height not found
          if (isFinite(q)) { // ensure that q is a finite number. A logical height value.
            BlockByHeight.get({
              blockHeight: q
            }, function(hash) {
              _resetSearch();
              $location.path(_languagePrefix() + '/block/' + hash.blockHash);
            }, function() { //not found, fail :(
              $scope.loading = false;
              _badQuery();
            });
          }
          else {
            $scope.loading = false;
            _badQuery();
          }
        });
      });
    });
  };

});


// Source: /root/explorer/sumcoin-explorer/node_modules/insight-sum-ui/public/src/js/controllers/status.js
'use strict';

angular.module('insight.status').controller('StatusController',
  function($scope, $routeParams, $location, Global,
           Status, Sync, getSocket, $interval) {

    $scope.global = Global;

    var infoTimer = null;
    var syncTimer = null;
    var socketStarted = false;

    function fetchStatus(q) {
      Status.get({q: 'get' + q},
        function(d) {
          $scope.loaded = 1;
          angular.extend($scope, d);
        },
        function(e) {
          $scope.error = 'API ERROR: ' +
            ((e && e.data) || 'Unable to query node');
        });
    }

    function fetchSync() {
      Sync.get({},
        function(sync) {
          $scope.sync = sync;
        },
        function(e) {
          $scope.sync = {
            error: 'Could not get sync information'
          };
        });
    }

    $scope.getStatus = function(q) {
      fetchStatus(q);

      if (q === 'Info' && !infoTimer) {
        infoTimer = $interval(function() {
          fetchStatus('Info');
        }, 5000);
      }
    };

    $scope.humanSince = function(time) {
      if (!time) return '';
      return moment.unix(time / 1000).max().fromNow();
    };

    var socket = getSocket($scope);

    function startSocket() {
      if (socketStarted) return;
      socketStarted = true;

      socket.emit('subscribe', 'sync');

      socket.on('status', function(sync) {
        $scope.sync = sync;
      });
    }

    socket.on('connect', startSocket);

    $scope.getSync = function() {
      fetchSync();
      startSocket();

      if (!syncTimer) {
        syncTimer = $interval(fetchSync, 2000);
      }
    };

    $scope.$on('$destroy', function() {
      if (infoTimer) $interval.cancel(infoTimer);
      if (syncTimer) $interval.cancel(syncTimer);
    });
  });


// Source: /root/explorer/sumcoin-explorer/node_modules/insight-sum-ui/public/src/js/controllers/transactions.js
'use strict';

angular.module('insight.transactions').controller('transactionsController',
function($scope, $rootScope, $routeParams, $location, Global, Transaction, TransactionsByBlock, TransactionsByAddress) {
  $scope.global = Global;
  $scope.loading = false;
  $scope.loadedBy = null;

  var pageNum = 0;
  var pagesTotal = 1;
  var COIN = 100000000;

  var _aggregateItems = function(items) {
    if (!items) return [];

    var l = items.length;

    var ret = [];
    var tmp = {};
    var u = 0;

    for(var i=0; i < l; i++) {

      var notAddr = false;
      // non standard input
console.log("item", items[i]);
      if (items[i].scriptSig && !items[i].addr) {
        items[i].addr = 'Unparsed address [' + u++ + ']';
        items[i].notAddr = true;
        notAddr = true;
      }

      // non standard output
      if (items[i].scriptPubKey && !items[i].scriptPubKey.addresses) {
        items[i].scriptPubKey.addresses = ['Unparsed address [' + u++ + ']'];
        items[i].notAddr = true;
        notAddr = true;
      }

      // multiple addr at output
      if (items[i].scriptPubKey && items[i].scriptPubKey.addresses.length > 1) {
        items[i].addr = items[i].scriptPubKey.addresses.join(',');
        ret.push(items[i]);
        continue;
      }

      var addr = items[i].addr || (items[i].scriptPubKey && items[i].scriptPubKey.addresses[0]);

      if (!tmp[addr]) {
        tmp[addr] = {};
        tmp[addr].valueSat = 0;
        tmp[addr].count = 0;
        tmp[addr].addr = addr;
        tmp[addr].items = [];
      }
      tmp[addr].isSpent = items[i].spentTxId;

      tmp[addr].doubleSpentTxID = tmp[addr].doubleSpentTxID   || items[i].doubleSpentTxID;
      tmp[addr].doubleSpentIndex = tmp[addr].doubleSpentIndex || items[i].doubleSpentIndex;
      tmp[addr].dbError = tmp[addr].dbError || items[i].dbError;
      tmp[addr].valueSat += Math.round(items[i].value * COIN);
      tmp[addr].items.push(items[i]);
      tmp[addr].notAddr = notAddr;

      if (items[i].unconfirmedInput)
        tmp[addr].unconfirmedInput = true;

      tmp[addr].count++;
    }

    angular.forEach(tmp, function(v) {
      v.value    = v.value || parseInt(v.valueSat) / COIN;
      ret.push(v);
    });
    return ret;
  };

  var _processTX = function(tx) {
    tx.vinSimple = _aggregateItems(tx.vin);
    tx.voutSimple = _aggregateItems(tx.vout);
  };

  var _paginate = function(data) {
    $scope.loading = false;

    pagesTotal = data.pagesTotal;
    pageNum += 1;

    data.txs.forEach(function(tx) {
      _processTX(tx);

      $scope.txs.push(tx);

      /*
       * If an unconfirmed payment already exists when this
       * address page is loaded/reloaded, expose it to the same
       * payment tracker.
       */

    });
  };

  var _byBlock = function() {
    TransactionsByBlock.get({
      block: $routeParams.blockHash,
      pageNum: pageNum
    }, function(data) {
      _paginate(data);
    });
  };

  var _byAddress = function () {
    TransactionsByAddress.get({
      address: $routeParams.addrStr,
      pageNum: pageNum
    }, function(data) {
      _paginate(data);
    });
  };

  var _findTx = function(txid) {
    Transaction.get({
      txId: txid
    }, function(tx) {
      $rootScope.titleDetail = tx.txid.substring(0,7) + '...';
      $rootScope.flashMessage = null;
      $scope.tx = tx;
      _processTX(tx);

      /*
       * The transaction has now been successfully obtained from
       * Insight. Give this exact object to AddressController.
       *
       * This is the SAME tx object used to draw the transaction
       * card, so payment tracking no longer performs a second
       * competing lookup.
       */


      $scope.txs.unshift(tx);
    }, function(e) {
      if (e.status === 400) {
        $rootScope.flashMessage = 'Invalid Transaction ID: ' + $routeParams.txId;
      }
      else if (e.status === 503) {
        $rootScope.flashMessage = 'Backend Error. ' + e.data;
      }
      else {
        $rootScope.flashMessage = 'Transaction Not Found';
      }

      $location.path(
        /^\/es(?:\/|$)/.test($location.path()) ?
          '/es/' :
          '/'
      );
    });
  };

  $scope.findThis = function() {
    _findTx($routeParams.txId);
  };

  //Initial load
  $scope.load = function(from) {
    $scope.loadedBy = from;
    $scope.loadMore();
  };

  //Load more transactions for pagination
  $scope.loadMore = function() {
    if (pageNum < pagesTotal && !$scope.loading) {
      $scope.loading = true;

      if ($scope.loadedBy === 'address') {
        _byAddress();
      }
      else {
        _byBlock();
      }
    }
  };

  // Highlighted txout
  if ($routeParams.v_type == '>' || $routeParams.v_type == '<') {
    $scope.from_vin = $routeParams.v_type == '<' ? true : false;
    $scope.from_vout = $routeParams.v_type == '>' ? true : false;
    $scope.v_index = parseInt($routeParams.v_index);
    $scope.itemsExpanded = true;
  }

  //Init without txs
  $scope.txs = [];

  $scope.$on('tx', function(event, txid) {
    _findTx(txid);
  });

  /*
   * Confirmations 2-6 for an actively tracked payment.
   *
   * Change ONLY the confirmation count already displayed by
   * the existing transaction card. No transaction-array rebuild,
   * no route reload and no layout changes.
   */
  $scope.$on('confirmation:update', function(event, data) {

    if (
      !data ||
      !data.txid
    ) {
      return;
    }

    angular.forEach(
      $scope.txs || [],
      function(tx) {

        if (
          tx &&
          tx.txid === data.txid
        ) {

          tx.confirmations =
            Number(
              data.confirmations || 0
            );
        }
      }
    );

    /*
     * Also covers the standalone tx controller state if present.
     */
    if (
      $scope.tx &&
      $scope.tx.txid === data.txid
    ) {

      $scope.tx.confirmations =
        Number(
          data.confirmations || 0
        );
    }

  });

});

angular.module('insight.transactions').controller('SendRawTransactionController',
  function($scope, $http) {
  $scope.transaction = '';
  $scope.status = 'ready';  // ready|loading|sent|error
  $scope.txid = '';
  $scope.error = null;

  $scope.formValid = function() {
    return !!$scope.transaction;
  };
  $scope.send = function() {
    var postData = {
      rawtx: $scope.transaction
    };
    $scope.status = 'loading';
    $http.post(window.apiPrefix + '/tx/send', postData)
      .success(function(data, status, headers, config) {
        if(typeof(data.txid) != 'string') {
          // API returned 200 but the format is not known
          $scope.status = 'error';
          $scope.error = 'The transaction was sent but no transaction id was got back';
          return;
        }

        $scope.status = 'sent';
        $scope.txid = data.txid;
      })
      .error(function(data, status, headers, config) {
        $scope.status = 'error';
        if(data) {
          $scope.error = data;
        } else {
          $scope.error = "No error message given (connection error?)"
        }
      });
  };
});


